package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	r := bufio.NewReaderSize(os.Stdin, 64*1024)
	max, cur := 0, 0
	has, first := false, true
	flush := func() {
		if !has {
			return
		}
		if first || cur > max {
			max = cur
			first = false
		}
		cur, has = 0, false
	}
	for {
		b, err := r.ReadByte()
		if err != nil {
			break
		}
		if b >= '0' && b <= '9' {
			cur = cur*10 + int(b-'0')
			has = true
		} else {
			flush()
		}
	}
	flush()
	fmt.Printf("max=%d\n", max)
}

