		}
	}
	if nonSpace {
		c++
	}
	fmt.Printf("words=%d\n", c)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	r := bufio.NewReaderSize(os.Stdin, 64*1024)
	buf := make([]byte, 64*1024)
	lines, chars := 0, 0
	for {
		n, err := r.Read(buf)
		for i := 0; i < n; i++ {
			chars++
			if buf[i] == '\n' {
				lines++
			}
		}
		if err != nil {
			break
		}
	}
	fmt.Printf("lines=%d chars=%d\n", lines, chars)
}

